{{
  (() => {
    const all = Get_Articles_Options.data || [];
    const raw = (sel_article.filterText || "").trim().toLowerCase();
    const selectedId = appsmith.store.nouvel_article_id || "";

    if (!raw) {
      if (!selectedId) return all.slice(0, 100);
      const sel = all.find(a => a.value === selectedId);
      return sel ? [sel, ...all.filter(a => a.value !== selectedId).slice(0, 99)] : all.slice(0, 100);
    }

    const cleanSearch = raw.replace(/[\s\-\/]+/g, "");
    const words = raw.split(/\s+/).filter(Boolean);

    const matches = all.filter(item => {
      const label = (item.label || "").toLowerCase();
      const refClean = (item.Ref_Fournisseur || "").toLowerCase().replace(/[\s\-\/]+/g, "");
      const ancClean = (item.Anciennes_References || "").toLowerCase().replace(/[\s\-\/]+/g, "");
      const eanClean = (item.Code_Barre || "").toLowerCase().replace(/[\s\-\/]+/g, "");

      const matchRef = cleanSearch.length >= 2 && (
        refClean.includes(cleanSearch) ||
        ancClean.includes(cleanSearch) ||
        eanClean.includes(cleanSearch)
      );
      const matchWords = words.every(w => label.includes(w));

      return matchRef || matchWords;
    });

    if (selectedId && !matches.some(m => m.value === selectedId)) {
      const sel = all.find(a => a.value === selectedId);
      if (sel) return [sel, ...matches.slice(0, 99)];
    }

    return matches.slice(0, 100);
  })()
}}
